#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# GitAway: the money setup only the captain can do (run: pixi run setup-money).
#   1. Railway: confirm this folder is linked to project gitaway, service web
#   2. ANTHROPIC_API_KEY      (creator import, Claude Haiku)          secret
#   3. GITAWAY_ADMIN_EMAILS   (who may open /admin)                   public
#   4. GITAWAY_CONTACT_EMAIL  (the address /privacy, /terms and Plan it for me show) public
#   5. Stripe account, test mode first
#   6. STRIPE_SECRET_KEY                                              secret
#   7. Stripe webhook /stripe/webhook (checkout.session.completed and checkout.session.async_payment_succeeded) -> STRIPE_WEBHOOK_SECRET (secret)
#   8. PLAN_FOR_ME_PRICE_CENTS (optional)                             public
#   9. PLAN_FOR_ME_REVIEW (optional: the founder check, 1 or 0)       public
#  10. Redeploy web so the running site reads them (asks first)
# Every value goes to Railway (service web) and nowhere else: no .env, no screen, no shell history.
# Secrets are read hidden and handed to `railway variable set NAME --stdin` (the stdin form of
# `railway variables --set`), so they are never on a command line either; public values use
# `railway variables --set`. Each set uses --skip-deploys; stage 8 offers one redeploy.
# The webhook path is /stripe/webhook (F-193): the wizard looks for it in the code and on the live site,
# and WEBHOOK_PATH=/other/path overrides it.

PROJECT=gitaway
ENVIRONMENT=production
SERVICE=web
SITE=https://gitaway.me
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

SET_ON_RAILWAY=()   # names set this run (never values)
KEPT=()             # names already on Railway that the captain kept
RAILWAY_NAMES=""    # names already on the web service
LINKED_PROJECT=""; LINKED_ENV=""; LINKED_SERVICE=""

ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# railway_check: reads `railway status`; success when it shows project gitaway, environment production, service web.
railway_check() {
  local out
  out=$(railway status 2>&1) || true
  LINKED_PROJECT=$(awk '/^Project:/ {sub(/^Project:[ \t]*/, ""); print; exit}' <<<"$out")
  LINKED_ENV=$(awk '/^Environment:/ {sub(/^Environment:[ \t]*/, ""); print; exit}' <<<"$out")
  LINKED_SERVICE=$(awk 'f && NF {print $1; exit} /^Linked service/ {f=1}' <<<"$out")
  note "railway status: project '${LINKED_PROJECT:-none}' · environment '${LINKED_ENV:-none}' · service '${LINKED_SERVICE:-none}'"
  [[ "$LINKED_PROJECT" == "$PROJECT" && "$LINKED_ENV" == "$ENVIRONMENT" && "$LINKED_SERVICE" == "$SERVICE" ]]
}

# load_names: the variable NAMES on the web service. Values pass through jq and are dropped; nothing is printed.
load_names() {
  RAILWAY_NAMES=""
  if command -v jq >/dev/null 2>&1; then
    RAILWAY_NAMES=$(railway variable list --service "$SERVICE" --json 2>/dev/null | jq -r 'keys[]' 2>/dev/null) || RAILWAY_NAMES=""
  fi
}

# wanted NAME: success when NAME should be asked for now (not on Railway yet, or the captain chooses to replace it).
wanted() {
  if grep -qxF "$1" <<<"$RAILWAY_NAMES"; then
    if confirm "$1 is already set on Railway. Replace it?"; then return 0; fi
    KEPT+=("$1")
    note "kept the current $1"
    return 1
  fi
  return 0
}

# redact TEXT SECRET: TEXT's last lines with SECRET blanked out, for showing a Railway error.
redact() {
  local text="$1" secret="${2:-}"
  if [[ -n "$secret" ]]; then text="${text//"$secret"/<hidden>}"; fi
  printf '%s' "$text" | tail -n 3
}

# put_secret NAME VALUE: VALUE goes to Railway on stdin (printf is a builtin: no process ever has it as an argument).
put_secret() {
  local name="$1" value="$2" out
  if out=$(printf '%s' "$value" | railway variable set "$name" --stdin --service "$SERVICE" --skip-deploys 2>&1); then
    SET_ON_RAILWAY+=("$name")
    ok "set $name on Railway (service $SERVICE); value not shown"
  else
    warn "Railway did not take $name: $(redact "$out" "$value")"
    SKIPPED+=("$name on Railway (rerun: pixi run setup-money)")
  fi
}

# put_public NAME VALUE: a value that is not secret, with railway variables --set.
put_public() {
  local name="$1" value="$2" out
  if out=$(railway variables --set "$name=$value" --service "$SERVICE" --skip-deploys 2>&1); then
    SET_ON_RAILWAY+=("$name")
    ok "set $name=$value on Railway (service $SERVICE)"
  else
    warn "Railway did not take $name: $(redact "$out")"
    SKIPPED+=("$name on Railway (rerun: pixi run setup-money)")
  fi
}

# The Stripe webhook path: F-193's route if this checkout has it, else the planned path.
WEBHOOK_IN_CODE=0
if [[ -n "${WEBHOOK_PATH:-}" ]]; then
  if grep -rqF -- "$WEBHOOK_PATH" "$ROOT/gitaway" "$ROOT/main.py" 2>/dev/null; then WEBHOOK_IN_CODE=1; fi
else
  WEBHOOK_PATH=/stripe/webhook   # F-193's route (fh-saas's own default path)
  for p in /stripe/webhook; do
    if grep -rqF -- "\"$p\"" "$ROOT/gitaway" "$ROOT/main.py" 2>/dev/null; then WEBHOOK_PATH=$p; WEBHOOK_IN_CODE=1; break; fi
  done
fi

run_wizard() {

TOTAL_STAGES=10
ENV_FILE=/dev/null   # values live on Railway only: the library never reads or writes a local .env here

banner "GitAway money setup: Anthropic, admin, Stripe"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Railway: project gitaway, service web"
say "Every value goes to Railway, project $PROJECT, service $SERVICE ($SITE). First, make sure that is where it lands."
if ! command -v railway >/dev/null 2>&1; then
  warn "The Railway CLI is not installed."
  step "Install it (https://docs.railway.com/guides/cli), run: railway login, then rerun: pixi run setup-money"
  exit 1
fi
if ! railway whoami >/dev/null 2>&1; then
  warn "You are not signed in to Railway."
  step "Run: railway login   then rerun: pixi run setup-money"
  exit 1
fi
until railway_check; do
  warn "This folder is not linked to $PROJECT / $ENVIRONMENT / $SERVICE (the autopilot worktree was linked to appcol on 2026-11-06)."
  if confirm "Link this folder to project $PROJECT, environment $ENVIRONMENT, service $SERVICE now?"; then
    railway link --project "$PROJECT" --environment "$ENVIRONMENT" --service "$SERVICE" >/dev/null 2>&1 \
      || { warn "railway link failed. Run it yourself in another terminal:"; step "railway link --project $PROJECT --environment $ENVIRONMENT --service $SERVICE"; pause "Press Enter to check again"; }
  else
    say "Stopped. Nothing was changed."
    exit 1
  fi
done
ok "linked to project $LINKED_PROJECT, environment $LINKED_ENV, service $LINKED_SERVICE"
load_names
if [[ -z "$RAILWAY_NAMES" ]]; then note "Could not list the service's variable names (install jq), so every value is asked for."; fi
pause "Press Enter for the Anthropic key"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Anthropic: the key for creator import"
say "ANTHROPIC_API_KEY switches on drafting a trip from a creator's post (Claude Haiku; docs/ai-usage.md)."
if wanted ANTHROPIC_API_KEY; then
  open_url "https://console.anthropic.com/settings/keys"
  step "Sign in (it may move you to platform.claude.com). Billing must have credit, or every draft fails."
  step "API keys → Create key → name it gitaway-web → Add."
  step "Copy the key now: it starts sk-ant- and is shown only once."
  step "Recommended: Limits → set a monthly spend limit."
  anthropic_key=""
  while :; do
    ask_secret anthropic_key "Paste the key (hidden; Enter alone skips):" || anthropic_key=""
    if [[ -z "$anthropic_key" || "$anthropic_key" == sk-ant-* ]]; then break; fi
    warn "That does not start with sk-ant-. Copy the whole key and paste again."
  done
  if [[ -n "$anthropic_key" ]]; then put_secret ANTHROPIC_API_KEY "$anthropic_key"
  else SKIPPED+=("ANTHROPIC_API_KEY (rerun: pixi run setup-money)"); fi
  unset anthropic_key
fi
pause "Press Enter for the admin emails"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Admin page: who may open /admin"
say "GITAWAY_ADMIN_EMAILS lists the sign-in addresses that may open $SITE/admin"
say "(take down, restore, reports, drafting a creator's post)."
note "Use the address you sign in to GitAway with; it must be a verified one. Separate several with commas."
if wanted GITAWAY_ADMIN_EMAILS; then
  admin_emails=""
  while :; do
    ask admin_emails "Admin email address(es) (Enter alone skips):" || admin_emails=""
    admin_emails=$(printf '%s' "$admin_emails" | tr ';[:space:]' ',' | tr -s ',' | sed 's/^,//; s/,$//')
    if [[ -z "$admin_emails" ]]; then break; fi
    bad=0
    IFS=',' read -ra parts <<<"$admin_emails"
    for e in "${parts[@]}"; do
      if ! [[ "$e" =~ ^[^@]+@[^@]+\.[^@]+$ ]]; then bad=1; fi
    done
    if (( bad == 0 )); then break; fi
    warn "\"$admin_emails\" does not look like email addresses. Try again."
  done
  if [[ -n "$admin_emails" ]]; then put_public GITAWAY_ADMIN_EMAILS "$admin_emails"
  else SKIPPED+=("GITAWAY_ADMIN_EMAILS (nobody can open /admin until it is set)"); fi
fi
pause "Press Enter for the contact email"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Contact email: the address people write to"
say "GITAWAY_CONTACT_EMAIL is the address /privacy, /terms and the Plan it for me pages show for questions, refunds and deleting data."
note "A mailbox you read: the promise says \"Email us within 7 days for a full refund\"."
if wanted GITAWAY_CONTACT_EMAIL; then
  contact_email=""
  while :; do
    ask contact_email "Contact email address (Enter alone skips):" || contact_email=""
    contact_email=$(printf '%s' "$contact_email" | tr -d '[:space:]')
    if [[ -z "$contact_email" || "$contact_email" =~ ^[^@,]+@[^@,]+\.[^@,]+$ ]]; then break; fi
    warn "\"$contact_email\" does not look like one email address. Try again."
  done
  if [[ -n "$contact_email" ]]; then put_public GITAWAY_CONTACT_EMAIL "$contact_email"
  else SKIPPED+=("GITAWAY_CONTACT_EMAIL (the legal pages and Plan it for me have no address to show)"); fi
fi
pause "Press Enter for Stripe"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Stripe: an account, test mode first"
say "Plan for me takes a one-time payment through Stripe Checkout. Start in test mode: no real money moves,"
say "and test cards (4242 4242 4242 4242) go through."
step "No Stripe account yet: sign up (email, name, password), verify the email. Test mode works before activation."
step "Already have one: sign in, then switch on Test mode (newer dashboards: open a Sandbox) at the top."
note "Live mode later needs the account activated (business details, bank account). Describe GitAway as a"
note "trip-planning service charging its own planning fee; travel bookings are paid to partners, not through Stripe."
if confirm "Do you need to create a Stripe account?"; then
  open_url "https://dashboard.stripe.com/register"
else
  open_url "https://dashboard.stripe.com/test/dashboard"
fi
pause "Press Enter once you are in the Stripe dashboard"
stripe_mode="test"
if confirm "Set up LIVE mode instead of test mode (real cards are charged; needs an activated account)?"; then stripe_mode="live"; fi
mode_path=""
if [[ "$stripe_mode" == test ]]; then mode_path=/test; fi
ok "Stripe $stripe_mode mode"
pause "Press Enter for the secret key"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Stripe: the secret key ($stripe_mode mode)"
say "STRIPE_SECRET_KEY lets GitAway open a Checkout page for Plan for me."
if wanted STRIPE_SECRET_KEY; then
  open_url "https://dashboard.stripe.com${mode_path}/apikeys"
  step "Developers → API keys → Standard keys → Secret key → Reveal (in a Sandbox, open the sandbox first)."
  step "Copy it: it starts sk_${stripe_mode}_."
  note "A live secret key is shown once: if it is hidden, Create secret key, name it gitaway-web, copy it."
  stripe_key=""
  while :; do
    ask_secret stripe_key "Paste the secret key (hidden; Enter alone skips):" || stripe_key=""
    if [[ -z "$stripe_key" || "$stripe_key" == sk_${stripe_mode}_* ]]; then break; fi
    warn "That does not start with sk_${stripe_mode}_ (wrong mode, or the publishable pk_ key?). Paste again."
  done
  if [[ -n "$stripe_key" ]]; then put_secret STRIPE_SECRET_KEY "$stripe_key"
  else SKIPPED+=("STRIPE_SECRET_KEY (rerun: pixi run setup-money)"); fi
  unset stripe_key
fi
pause "Press Enter for the webhook"

# ── 7 ─────────────────────────────────────────────────────────────────────
webhook_url="$SITE$WEBHOOK_PATH"
stage "Stripe: the webhook for paid checkouts ($stripe_mode mode)"
say "Stripe tells GitAway a payment went through by calling:"
say "  $webhook_url   (events: checkout.session.completed and checkout.session.async_payment_succeeded)"
if (( WEBHOOK_IN_CODE == 0 )); then
  warn "$WEBHOOK_PATH is not in this checkout's code (F-193's route is /stripe/webhook)."
  note "Check the real route there before saving. If it differs, Ctrl-C and rerun: WEBHOOK_PATH=/the/path pixi run setup-money"
fi
if wanted STRIPE_WEBHOOK_SECRET; then
  open_url "https://dashboard.stripe.com${mode_path}/webhooks"
  step "Developers → Webhooks → Add destination (older dashboards: Add endpoint)."
  step "Events from: Your account. Select events: checkout.session.completed and checkout.session.async_payment_succeeded → Continue."
  step "Destination type: Webhook endpoint → Continue."
  step "Endpoint URL: $webhook_url → Create destination (or Add endpoint)."
  step "On the new endpoint: Signing secret → Reveal → copy it (starts whsec_)."
  note "Test and live mode have separate endpoints and separate signing secrets."
  webhook_secret=""
  while :; do
    ask_secret webhook_secret "Paste the signing secret (hidden; Enter alone skips):" || webhook_secret=""
    if [[ -z "$webhook_secret" || "$webhook_secret" == whsec_* ]]; then break; fi
    warn "That does not start with whsec_. Paste the endpoint's signing secret again."
  done
  if [[ -n "$webhook_secret" ]]; then put_secret STRIPE_WEBHOOK_SECRET "$webhook_secret"
  else SKIPPED+=("STRIPE_WEBHOOK_SECRET (rerun: pixi run setup-money)"); fi
  unset webhook_secret
fi
say "Asking the live site whether $WEBHOOK_PATH exists (an unsigned POST must be refused, not missing):"
code=$(curl -s -o /dev/null -m 10 -w '%{http_code}' -X POST -H 'Content-Type: application/json' --data '{}' "$webhook_url" 2>/dev/null) || true
case "$code" in
  400|401) ok "$code: the route is live and refuses unsigned calls" ;;
  404|405) warn "$code: not on gitaway.me yet. Stripe's deliveries fail until F-193 is deployed (Stripe retries for up to 3 days)." ;;
  2??)     warn "$code: it ACCEPTED an unsigned call. The handler must check Stripe's signature; tell the developer before going live."
           SKIPPED+=("webhook accepted an unsigned POST: check its signature check") ;;
  30?|403) warn "$code: the route is behind sign-in or the role gate (gitaway/access.py). Stripe cannot sign in: it must be an open route."
           SKIPPED+=("webhook answered $code: put it on the open list in gitaway/access.py") ;;
  *)       warn "answered '${code:-nothing}'. Check $webhook_url later with Stripe's 'Send test event'." ;;
esac
pause "Press Enter for the price"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Plan for me: the price (optional)"
say "PLAN_FOR_ME_PRICE_CENTS is the one-time price in whole cents: 1900 is \$19.00."
say "Leave it empty to keep the price built into the app."
if wanted PLAN_FOR_ME_PRICE_CENTS; then
  price_cents=""
  while :; do
    ask price_cents "Price in cents (Enter alone skips):" || price_cents=""
    if [[ -z "$price_cents" ]]; then break; fi
    if [[ "$price_cents" =~ ^[0-9]+$ ]] && (( 10#$price_cents >= 50 )); then price_cents=$((10#$price_cents)); break; fi
    warn "Whole cents only, at least 50 (Stripe's smallest US charge is \$0.50)."
  done
  if [[ -n "$price_cents" ]]; then
    printf -v dollars '%d.%02d' $((price_cents / 100)) $((price_cents % 100))
    if confirm "Charge \$$dollars for Plan for me?"; then put_public PLAN_FOR_ME_PRICE_CENTS "$price_cents"
    else note "price not set"; fi
  fi
fi
pause "Press Enter for the founder check"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Plan it for me: the founder check (optional)"
say "PLAN_FOR_ME_REVIEW is on unless it is 0: a built plan waits on $SITE/admin for your \"Send to family\" before the family sees it."
say "0 delivers at once (the pages then say \"in a few minutes\"). Leave it empty to keep the check on."
if wanted PLAN_FOR_ME_REVIEW; then
  review=""
  while :; do
    ask review "Founder check, 1 (on) or 0 (off) (Enter alone skips):" || review=""
    if [[ -z "$review" || "$review" == 0 || "$review" == 1 ]]; then break; fi
    warn "Type 1 or 0."
  done
  if [[ -n "$review" ]]; then put_public PLAN_FOR_ME_REVIEW "$review"; fi
fi
pause "Press Enter to finish"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Load the new values on gitaway.me"
if (( ${#SET_ON_RAILWAY[@]} == 0 )); then
  say "Nothing changed on Railway, so there is nothing to reload."
else
  say "Set on Railway (service $SERVICE), names only: ${SET_ON_RAILWAY[*]}"
  say "They were saved with --skip-deploys, so the running site does not read them yet."
  note "About to deploy autopilot/booking-creators? Say no: that deploy loads them (docs/launch/ship-checklist.md)."
  if confirm "Redeploy web now, same code, so it reads them? (about a minute; brief 502s while the volume moves)"; then
    if out=$(railway redeploy --service "$SERVICE" --yes 2>&1); then
      ok "redeploy started"
      step "Watch it:  railway deployment list --service $SERVICE --limit 3"
      step "Then:      curl -s -o /dev/null -w '%{http_code}\\n' \"$SITE/healthz?q=\$RANDOM\"   (expect 200)"
    else
      warn "redeploy did not start: $(redact "$out")"
      SKIPPED+=("redeploy web (dashboard: web → Deployments → Redeploy)")
    fi
  else
    SKIPPED+=("redeploy web, or deploy the branch, so the new values load")
  fi
fi
pause "Press Enter for the summary"

finish
if (( ${#SET_ON_RAILWAY[@]} )); then note "set on Railway ($PROJECT / $SERVICE): ${SET_ON_RAILWAY[*]}"; fi
if (( ${#KEPT[@]} )); then note "kept as they were: ${KEPT[*]}"; fi
note "Check once the branch is live: signed in with an admin address, $SITE/admin opens;"
note "$SITE/creators/import no longer says drafting is not switched on; Stripe → Webhooks shows deliveries succeeding."
printf '\n'
}

run_wizard "$@"; exit
